   // (the release build only runs on tags)
   name: "Build zigbuild (Debug)",
   if: isZigbuild,
+  env: zigbuildEnv,
   run: `cargo zigbuild -p dprint --locked --target ${matrix.target}.${matrix.zigbuild_glibc}`,
 }, {
   name: "Check glibc requirement (Debug)",
